	private static void assertExpectedGraphRow(List<BindingSet> rows, String query, String route) {
		assertThat(rows).as("%s result for %s", route, query).hasSize(1);
		BindingSet row = rows.get(0);
		assertThat(row.getBindingNames()).as("%s binding names for %s", route, query)
				.containsExactlyInAnyOrder("g");
		assertThat(row.getValue("g")).as("%s graph name for %s", route, query).isEqualTo(G1);
	}

	private List<BindingSet> evaluate(String query, int optimization) {
		return evaluate(query, optimization, List.of(G1), List.of());
	}

	private List<BindingSet> evaluate(String query, int optimization, List<Resource> contexts,
			List<Statement> statements) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Resource> getContextIDs() {
				return new CloseableIteratorIteration<>(contexts.iterator());
			}

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(statements.stream()
						.filter(statement -> subject == null || subject.equals(statement.getSubject()))
						.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
						.filter(statement -> object == null || object.equals(statement.getObject()))
						.filter(statement -> matchesContext(statement, contexts))
						.iterator());
			}
		}, null);
		TupleExpr expression = new QueryRoot(
				QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr());
		if (optimization == 1) {
			new SameTermFilterOptimizer().optimize(expression, null, EmptyBindingSet.getInstance());
		}
		if (optimization == 2) {
			strategy.optimize(expression, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		}
		try (CloseableIteration<BindingSet> rows = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			return QueryResults.asList(rows);
		}
	}

	private static boolean matchesContext(Statement statement, Resource... contexts) {
		if (contexts == null || contexts.length == 0) {
			return true;
		}
		for (Resource context : contexts) {
			if (Objects.equals(context, statement.getContext())) {
				return true;
			}
		}
		return false;
	}

	private static BindingSet graphRow(IRI graph, Value object) {
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("g", graph);
		if (object != null) {
			bindings.addBinding("o", object);
		}
		return bindings;
	}

	private static BindingSet seedRow() {
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("seed", VF.createIRI("urn:seed"));
		return bindings;
	}
